service:
[Unit]
Description=Orbit Schedule {{id}}
X-Orbit-Schedule-ID={{id}}
X-Orbit-Command-SHA256={{command_hash}}
X-Orbit-Execution-Context={{context}}
X-Orbit-Timeout-Seconds={{timeout_seconds}}
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
User={{user}}
Group={{group}}
WorkingDirectory={{working_directory}}
ExecStart=/usr/bin/curl --disable --silent --fail --max-time 10 --proto =https --noproxy "*" --cacert /etc/orbit/agent/ca.pem --request POST --header "Idempotency-Key: ${INVOCATION_ID}" --output /dev/null https://gateway.orbit/api/v1/schedules/{{id}}/run
TimeoutStartSec=15

timer:
[Unit]
Description=Orbit Schedule timer {{id}}
X-Orbit-Schedule-ID={{id}}

[Timer]
OnCalendar={{calendar}}
Persistent=true
Unit=orbit-schedule-{{id}}.service

[Install]
WantedBy=timers.target

agentService:
[Unit]
Description=Orbit Schedule {{id}}
X-Orbit-Schedule-ID={{id}}
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
User={{user}}
Group={{group}}
WorkingDirectory={{working_directory}}
Environment="HOME={{home}}"
Environment="SHELL={{shell}}"
ExecStart=/usr/local/bin/orbit-agent service schedules-run {{id}}
ExecStopPost=+/usr/local/bin/orbit-agent service schedules-complete {{id}}
TimeoutStartSec={{timeout_seconds}}

directService:
[Unit]
Description=Orbit Schedule {{id}}
X-Orbit-Schedule-ID={{id}}
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
User={{user}}
Group={{group}}
WorkingDirectory={{working_directory}}
ExecStart=/usr/bin/env -i "PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin" "HOME={{home}}" "SHELL={{shell}}" "USER={{user}}" "LOGNAME={{user}}" "{{shell}}"{{login_shell}} /etc/orbit/schedules/{{id}}.sh
ExecStopPost=+/bin/sh /etc/orbit/schedules/{{id}}.complete
TimeoutStartSec={{timeout_seconds}}
